#!/usr/bin/env bash
# AI Assistance Disclosure:
# Tool: ChatGPT (model: GPT-6.1 Terra), date: 2026-11-06
# Scope: Updated implementation of local backend development startup and Floci endpoint configuration after RDS and MSK changes
# Author review: Verified correctness of env variables and migration jobs.

set -euo pipefail
cd "$(dirname "$0")/.."
[[ -s floci/docker/.generated.env ]] || { echo 'Run npm run dev-infra first.' >&2; exit 1; }
set -a
# Generated by the local Floci startup script.
source floci/docker/.generated.env
set +a
export KAFKA_BROKERS="${KAFKA_BROKERS_HOST:?Missing host Kafka endpoint in generated env}"
export KAFKA_AUTH_MODE=none
export COGNITO_JWKS_URI="http://localhost:4566/${COGNITO_USER_POOL_ID}/.well-known/jwks.json"
export AUTH_MODE=cognito
export AWS_ENDPOINT_URL=http://localhost:4566
export AWS_DEFAULT_REGION=us-east-1
export AWS_ACCESS_KEY_ID=test AWS_SECRET_ACCESS_KEY=test
export S3_ENDPOINT=http://localhost:4566 S3_PUBLIC_ENDPOINT=http://localhost:4566
export S3_REGION=us-east-1 S3_ACCESS_KEY_ID=test S3_SECRET_ACCESS_KEY=test
export S3_FORCE_PATH_STYLE=true
export USER_SERVICE_INTERNAL_TOKEN=local-internal-user-service-token
export INTERNAL_USER_SERVICE_TOKEN=local-internal-user-service-token
export INTERNAL_SUPPLIER_SERVICE_TOKEN=local-internal-supplier-service-token
export CREDIT_SERVICE_INTERNAL_TOKEN=local-internal-credit-service-token
export CREDIT_ESTIMATION_SERVICE_TOKEN=local-internal-estimation-service-token
export SUPPLIER_TIMEZONE=Asia/Singapore
export USER_API_TIMEOUT=5000 SUPPLIER_SERVICE_TIMEOUT_MS=5000 ESTIMATION_SERVICE_TIMEOUT_MS=5000
export COGNITO_ADMIN_GROUP_NAME=AdminGroup COGNITO_SUPERADMIN_GROUP_NAME=SuperAdminGroup
export KAFKA_TOPIC_USER_EVENTS=user-events KAFKA_TOPIC_USER_DLQ=user-events-dlq
export KAFKA_TOPIC_ERRAND_EVENTS=errand-events KAFKA_TOPIC_ERRAND_DLQ=errand-events-dlq

DATABASE_URL="$USER_DATABASE_URL_HOST" npx prisma migrate deploy --schema=user-service/backend/prisma/schema.prisma
npm run prisma:generate --workspace=@relay/errand-backend
DATABASE_URL="$ERRAND_DATABASE_URL_HOST" npx prisma db execute --schema=errand-service/backend/prisma/schema.prisma --file=errand-service/backend/prisma/dev-backfill.sql
DATABASE_URL="$ERRAND_DATABASE_URL_HOST" npx prisma db push --schema=errand-service/backend/prisma/schema.prisma
DATABASE_URL="$CREDIT_DATABASE_URL_HOST" npm run prisma:generate --workspace=@relay/credit-backend
DATABASE_URL="$CREDIT_DATABASE_URL_HOST" npx prisma migrate deploy --schema=credit-service/backend/prisma/schema.prisma

npx concurrently --kill-others-on-fail \
  --names supplier,user,errand,credit,estimation,notification,user-publisher,errand-publisher \
  'PORT=3000 DB_HOST=localhost DB_PORT="$SUPPLIER_DATABASE_PORT" DB_USER=relay DB_PASSWORD="$SUPPLIER_DATABASE_PASSWORD" DB_NAME=relay USER_API_URL=http://localhost:3001 npm run dev --workspace=@relay/supplier-backend' \
  'PORT=3001 DATABASE_URL="$USER_DATABASE_URL_HOST" npm run dev --workspace=@relay/user-backend' \
  'PORT=3002 DATABASE_URL="$ERRAND_DATABASE_URL_HOST" USER_API_URL=http://localhost:3001 SUPPLIER_API_URL=http://localhost:3000 CREDIT_API_URL=http://localhost:3003 CREDIT_ESTIMATION_API_URL=http://localhost:3005 npm run dev --workspace=@relay/errand-backend' \
  'PORT=3003 DATABASE_URL="$CREDIT_DATABASE_URL_HOST" USER_API_URL=http://localhost:3001 npm run dev --workspace=@relay/credit-backend' \
  'PORT=3005 USER_API_URL=http://localhost:3001 npm run dev --workspace=@relay/credit-estimation-backend' \
  'PORT=3010 npm run dev --workspace=@relay/errand-notification-backend' \
  'DATABASE_URL="$USER_DATABASE_URL_HOST" npx tsx user-service/event-publisher/main.ts' \
  'DATABASE_URL="$ERRAND_DATABASE_URL_HOST" npx tsx errand-service/event-publisher/main.ts'
